import{_ as n,a0 as r,w as d,s as p,ao as o,I as a,x as i,a1 as t,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"Rails 之旅第 2 天：Rails 关联和拖动 div | LCTT x X-CMD","titleTemplate":false,"description":"Rails 之旅第 2 天：Rails 关联和拖动 div | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Rails 之旅第 2 天：Rails 关联和拖动 div | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Rails 之旅第 2 天：Rails 关联和拖动 div | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201110 Day 2- Rails associations - dragging divs around","title":"Rails 之旅第 2 天：Rails 关联和拖动 div","tag":"202012","desc":""},"relativePath":"202012/20201110 Day 2- Rails associations - dragging divs around.md","filePath":"[post].md"}'),u={name:"202012/20201110 Day 2- Rails associations - dragging divs around.md"};function g(b,s,f,h,T,k){const l=r("Link");return d(),p("div",null,[s[34]||(s[34]=o('<h1 id="rails-之旅第-2-天-rails-关联和拖动-div" tabindex="-1">Rails 之旅第 2 天：Rails 关联和拖动 div <a class="header-anchor" href="#rails-之旅第-2-天-rails-关联和拖动-div" aria-label="Permalink to “Rails 之旅第 2 天：Rails 关联和拖动 div”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202012/05/212345zz8jajhaj0hh8h2f.jpg" alt=""></p><p>大家好！今天是我搭建这个玩具项目的第 2 天。下面再来记录一下关于 Rails 的一些有趣的事情吧！</p><h3 id="目标-做一个冰箱诗歌论坛" tabindex="-1">目标：做一个冰箱诗歌论坛 <a class="header-anchor" href="#目标-做一个冰箱诗歌论坛" aria-label="Permalink to “目标：做一个冰箱诗歌论坛”">​</a></h3><p>我想做一种无聊的标准网站来学习 Rails，并且其他人可以与之互动，就像一个论坛一样! 但如果人们真的可以在网站上打字，那就会产生各种各样的问题（如果他们是垃圾邮件发送者怎么办？又或者只是言语刻薄？）。</p><p>我想到的第一个想法是，可以让人们与网站互动，但实际上却不能在网站上打字，那就是一个“冰箱诗歌论坛”，只给你一组固定的字，你就可以随意组合。</p><p>所以，这就是我们的计划！</p><p>我这个项目的目标是想知道我是否能用 Rails 来做其他的小型网络项目（而不是像我通常做的那样，使用一些更基本的东西，比如 Flask，或者放弃后端，用 Javascript 来写所有东西）。</p><h3 id="怎么把字拖来拖去呢-jquery-的可拖放-ui" tabindex="-1">怎么把字拖来拖去呢？jQuery 的可拖放 UI！ <a class="header-anchor" href="#怎么把字拖来拖去呢-jquery-的可拖放-ui" aria-label="Permalink to “怎么把字拖来拖去呢？jQuery 的可拖放 UI！”">​</a></h3><p>我想让大家能够把文字拖动起来，但我又不想写很多 Javascript。结果发现这超级简单 —— 有一个 jQuery 库可以做到，它叫做 <code>draggable</code>！一开始，拖动并不成功。</p>',10)),a("p",null,[s[1]||(s[1]=i("一开始拖动在手机上是不行的，但是有一个技巧可以让 jQuery UI 在手机上工作，叫做 ",-1)),t(l,{href:"https://github.com/furf/jquery-ui-touch-punch"},{default:e(()=>[...s[0]||(s[0]=[i("jQuery UI touch punch",-1)])]),_:1}),s[2]||(s[2]=i("。下面是它的样子（有兴趣看工作原理的可以查看源码，代码很少）。",-1))]),s[35]||(s[35]=a("blockquote",null,[a("p",null,[a("code",null,"banana"),i(),a("code",null,"forest"),i(),a("code",null,"cake"),i(),a("code",null,"is")])],-1)),s[36]||(s[36]=a("h3",{id:"一个有趣的-rails-功能-关联",tabindex:"-1"},[i("一个有趣的 Rails 功能：关联 "),a("a",{class:"header-anchor",href:"#一个有趣的-rails-功能-关联","aria-label":"Permalink to “一个有趣的 Rails 功能：关联”"},"​")],-1)),a("p",null,[s[4]||(s[4]=i("我以前从来没有使用过关系型 ORM，对于 Rails，我很兴奋的一件事就是想看看使用 Active Record 是什么样子的！今天我了解了 Rails 的 ORM 功能之一：",-1)),t(l,{href:"https://guides.rubyonrails.org/association_basics.html"},{default:e(()=>[...s[3]||(s[3]=[i("关联",-1)])]),_:1}),s[5]||(s[5]=i("。如果你像我一样对 ORM 完全不了解的话，那就来看看是怎么回事吧。",-1))]),s[37]||(s[37]=o(`<p>在我的论坛中，我有：</p><ul><li>用户</li><li>话题（我本来想把它叫做“线索”，但显然这在 Rails 中是一个保留词，所以现在叫做“话题”）。</li><li>帖子</li></ul><p>当显示一个帖子时，我需要显示创建该帖子的用户的用户名。所以我想我可能需要写一些代码来加载帖子，并为每个帖子加载用户，就像这样（在 Rails 中，<code>Post.where</code> 和 <code>User.find</code> 将会运行 SQL 语句，并将结果转化为 Ruby 对象）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@posts = Post.where(topic_id: id)</span></span>
<span class="line"><span>@posts.each do |post|</span></span>
<span class="line"><span>    user = User.find(post.user_id)</span></span>
<span class="line"><span>    post.user = user</span></span>
<span class="line"><span>end</span></span></code></pre></div>`,4)),a("p",null,[s[8]||(s[8]=i("这还不够好，它要为每个帖子做一次单独的 SQL 查询！我知道有一个更好的方法，我发现它叫做",-1)),t(l,{href:"https://guides.rubyonrails.org/association_basics.html"},{default:e(()=>[...s[6]||(s[6]=[i("关联",-1)])]),_:1}),s[9]||(s[9]=i("。这个链接是来自 ",-1)),t(l,{href:"https://guides.rubyonrails.org"},{default:e(()=>[...s[7]||(s[7]=[i("https://guides.rubyonrails.org",-1)])]),_:1}),s[10]||(s[10]=i(" 的指南，到目前为止，它对我很有帮助。",-1))]),s[38]||(s[38]=o('<p>基本上我需要做的就是：</p><ol><li>在 <code>User</code> 模型中添加一行 <code>has_many :post</code>。</li><li>在 <code>Post</code> 模型中添加一行 <code>belongs_to :user</code>。</li><li>Rails 现在知道如何将这两个表连接起来，尽管我没有告诉它要连接到什么列上！我认为这是因为我按照它所期望的惯例命名了 <code>posts</code> 表中的 <code>user_id</code> 列。</li><li>对 <code>User</code> 和 <code>Topic</code> 做完全相同的事情（一个主题也有很多帖子：<code>has_many :posts</code>）。</li></ol><p>然后我加载每一个帖子和它的关联用户的代码就变成了只有一行! 就是这一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@posts = @topic.posts.order(created_at: :asc).preload(:user)</span></span></code></pre></div>',4)),a("p",null,[s[12]||(s[12]=i("比起只有一行更重要的是，它不是单独做一个查询来获取每个帖子的用户，而是在 1 个查询中获取所有用户。显然，在 Rails 中，有一堆",-1)),t(l,{href:"https://blog.bigbinary.com/2013/07/01/preload-vs-eager-load-vs-joins-vs-includes.html"},{default:e(()=>[...s[11]||(s[11]=[i("不同的方法",-1)])]),_:1}),s[13]||(s[13]=i("来做类似的事情（预加载、急切加载、联接和包含？），我还不知道这些都是什么，但也许我以后会知道的。",-1))]),s[39]||(s[39]=o('<h3 id="一个有趣的-rails-功能-脚手架" tabindex="-1">一个有趣的 Rails 功能：脚手架！ <a class="header-anchor" href="#一个有趣的-rails-功能-脚手架" aria-label="Permalink to “一个有趣的 Rails 功能：脚手架！”">​</a></h3><p>Rails 有一个叫 <code>rails</code> 的命令行工具，它可以生成很多代码。例如，我想添加一个 <code>Topic</code> 模型/控制器。我不用去想在哪里添加所有的代码，可以直接运行</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rails generate scaffold Topic title:text</span></span></code></pre></div>',3)),a("p",null,[s[15]||(s[15]=i("并生成了一堆代码，这样我已经有了基本的端点来创建/编辑/删除主题（",-1)),s[16]||(s[16]=a("code",null,"Topic",-1)),s[17]||(s[17]=i("）。例如，这是我的",-1)),t(l,{href:"https://github.com/jvns/refrigerator-forum/blob/776b3227cfd7004cb1efb00ec7e3f82a511cbdc4/app/controllers/topics_controller.rb#L13-L15"},{default:e(()=>[...s[14]||(s[14]=[i("现在的主题控制器",-1)])]),_:1}),s[18]||(s[18]=i("，其中大部分我没有写（我只写了高亮的 3 行）。我可能会删除很多内容，但是有一个起点，让我可以扩展我想要的部分，删除我不想要的部分，感觉还不错。",-1))]),s[40]||(s[40]=o(`<h3 id="数据库迁移" tabindex="-1">数据库迁移！ <a class="header-anchor" href="#数据库迁移" aria-label="Permalink to “数据库迁移！”">​</a></h3><p><code>rails</code> 工具还可以生成数据库迁移! 例如，我决定要删除帖子中的 <code>title</code> 字段。</p><p>下面是我要做的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rails generate migration RemoveTitleFromPosts title:string</span></span>
<span class="line"><span>rails db:migrate</span></span></code></pre></div><p>就是这样 —— 只要运行几个命令行咒语就可以了! 我运行了几个这样的迁移，因为我改变了对我的数据库模式的设想。它是相当直接的，到目前为止 —— 感觉很神奇。</p><p>当我试图在一列中的某些字段为空的地方添加一个“不为空”（<code>not null</code>）约束时，情况就变得有点有趣了 —— 迁移失败。但我可以修复违例的记录，并轻松地重新运行迁移。</p><h3 id="今天就到这里吧" tabindex="-1">今天就到这里吧！ <a class="header-anchor" href="#今天就到这里吧" aria-label="Permalink to “今天就到这里吧！”">​</a></h3><p>明天，如果我有更多的进展，也许我会把它放在互联网上。</p><hr>`,9)),a("p",null,[s[20]||(s[20]=i("via: ",-1)),t(l,{href:"https://jvns.ca/blog/2020/11/10/day-2--rails-associations---dragging-divs-around/"},{default:e(()=>[...s[19]||(s[19]=[i("https://jvns.ca/blog/2020/11/10/day-2--rails-associations---dragging-divs-around/",-1)])]),_:1})]),a("p",null,[s[25]||(s[25]=i("作者：",-1)),t(l,{href:"https://jvns.ca/"},{default:e(()=>[...s[21]||(s[21]=[i("Julia Evans",-1)])]),_:1}),s[26]||(s[26]=i(" 选题：",-1)),t(l,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[22]||(s[22]=[i("lujun9972",-1)])]),_:1}),s[27]||(s[27]=i(" 译者：",-1)),t(l,{href:"https://github.com/wxy"},{default:e(()=>[...s[23]||(s[23]=[i("wxy",-1)])]),_:1}),s[28]||(s[28]=i(" 校对：",-1)),t(l,{href:"https://github.com/wxy"},{default:e(()=>[...s[24]||(s[24]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[31]||(s[31]=i("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[29]||(s[29]=[i("LCTT",-1)])]),_:1}),s[32]||(s[32]=i(" 原创编译，",-1)),t(l,{href:"https://linux.cn/"},{default:e(()=>[...s[30]||(s[30]=[i("Linux中国",-1)])]),_:1}),s[33]||(s[33]=i(" 荣誉推出",-1))])])}const y=n(u,[["render",g]]);export{v as __pageData,y as default};
